const APP_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>Salary Manager</title>\n<meta name=\"description\" content=\"Monthly salary plan, withdrawals and savings. Works offline; data stays on this phone.\">\n<meta name=\"theme-color\" content=\"#0c6a56\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-title\" content=\"Salary\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\">\n<link rel=\"manifest\" href=\"manifest.webmanifest\">\n<link rel=\"icon\" type=\"image/png\" href=\"icons/icon-192.png\">\n<link rel=\"apple-touch-icon\" href=\"icons/apple-touch-icon.png\">\n<style>\n@font-face{font-family:\"Bricolage Grotesque\";font-weight:500;font-style:normal;font-display:swap;src:url(\"fonts/bricolage-500.woff2\") format(\"woff2\")}\n@font-face{font-family:\"Bricolage Grotesque\";font-weight:700;font-style:normal;font-display:swap;src:url(\"fonts/bricolage-700.woff2\") format(\"woff2\")}\n@font-face{font-family:\"Public Sans\";font-weight:400;font-style:normal;font-display:swap;src:url(\"fonts/public-400.woff2\") format(\"woff2\")}\n@font-face{font-family:\"Public Sans\";font-weight:500;font-style:normal;font-display:swap;src:url(\"fonts/public-500.woff2\") format(\"woff2\")}\n@font-face{font-family:\"Public Sans\";font-weight:600;font-style:normal;font-display:swap;src:url(\"fonts/public-600.woff2\") format(\"woff2\")}\n@font-face{font-family:\"Public Sans\";font-weight:700;font-style:normal;font-display:swap;src:url(\"fonts/public-700.woff2\") format(\"woff2\")}\nhtml{-webkit-text-size-adjust:100%}\nbody{margin:0;padding-top:env(safe-area-inset-top,0px)}\nimg{max-width:100%}\n</style>\n<style>\n/* Layout: phone-first single column (max 620px), sticky month header, fixed bottom tabs.\nRows read like a bank passbook. Red = withdrawn (the original sheet's convention),\namber = envelope taken in parts, green = savings. */\n:root{\n--bg:#f2f5f3; --surface:#ffffff; --sunk:#e8eeeb; --ink:#13201b; --muted:#5a6a64; --line:#d8e1dd;\n--accent:#0c6a56; --accent-ink:#ffffff; --accent-soft:#dcefe8;\n--paid:#c0372d; --paid-soft:#fae6e3;\n--env:#a86300; --env-soft:#fbeed8;\n--save:#1d8248; --save-soft:#e0f2e7;\n--warn:#9a4b00; --warn-soft:#fdf0dd;\n--shadow:0 1px 2px rgba(19,32,27,.06),0 4px 14px rgba(19,32,27,.06);\n--font-display:\"Bricolage Grotesque\", ui-sans-serif, system-ui, sans-serif;\n--font-body:\"Public Sans\", ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n--r:12px;\n}\n@media (prefers-color-scheme: dark){ :root:not([data-theme=\"light\"]){\n--bg:#0e1412; --surface:#161f1c; --sunk:#1c2723; --ink:#e6eeea; --muted:#97a8a1; --line:#283530;\n--accent:#4cc4a3; --accent-ink:#062219; --accent-soft:#143a30;\n--paid:#ff8076; --paid-soft:#3b1c1a;\n--env:#f1aa45; --env-soft:#3a2a12;\n--save:#62d290; --save-soft:#163524;\n--warn:#f1aa45; --warn-soft:#3a2a12;\n--shadow:0 1px 2px rgba(0,0,0,.3),0 4px 14px rgba(0,0,0,.25);\ncolor-scheme:dark;\n}}\n:root[data-theme=\"dark\"]{\n--bg:#0e1412; --surface:#161f1c; --sunk:#1c2723; --ink:#e6eeea; --muted:#97a8a1; --line:#283530;\n--accent:#4cc4a3; --accent-ink:#062219; --accent-soft:#143a30;\n--paid:#ff8076; --paid-soft:#3b1c1a;\n--env:#f1aa45; --env-soft:#3a2a12;\n--save:#62d290; --save-soft:#163524;\n--warn:#f1aa45; --warn-soft:#3a2a12;\n--shadow:0 1px 2px rgba(0,0,0,.3),0 4px 14px rgba(0,0,0,.25);\ncolor-scheme:dark;\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml,body{background:var(--bg)}\nbody{color:var(--ink);font-family:var(--font-body);font-size:15px;line-height:1.45;font-variant-numeric:tabular-nums;padding-bottom:calc(76px + env(safe-area-inset-bottom,0px))}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--bg)}\n.wrap{max-width:620px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\nh1,h2,h3{font-family:var(--font-display);margin:0;text-wrap:balance;letter-spacing:-.01em}\nh2{font-size:18px;font-weight:700}\nbutton,input,select{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n/* header */\n.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--bg);border-bottom:1px solid var(--line)}\n.top .wrap{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-block:12px}\n.top h1{font-size:22px;font-weight:700}\n.top .sub{color:var(--muted);font-size:13px}\n.pill{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600;padding:3px 9px;border-radius:999px;background:var(--sunk);color:var(--muted);white-space:nowrap}\n.pill.open{background:var(--accent-soft);color:var(--accent)}\n.pill.paid{background:var(--paid-soft);color:var(--paid)}\n.pill.env{background:var(--env-soft);color:var(--env)}\n.pill.save{background:var(--save-soft);color:var(--save)}\n.pill.warn{background:var(--warn-soft);color:var(--warn)}\nmain.wrap{padding-block:16px 24px;display:flex;flex-direction:column;gap:20px}\nsection.view{display:flex;flex-direction:column;gap:20px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--shadow)}\n.summary{padding:16px;display:flex;flex-direction:column;gap:14px}\n.big-label{font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:600}\n.big{font-family:var(--font-display);font-size:36px;font-weight:700;line-height:1.05}\n.big small{font-size:16px;font-weight:500;color:var(--muted);margin-left:4px}\n.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}\n.stat{background:var(--sunk);border-radius:10px;padding:10px}\n.stat .k{font-size:12px;color:var(--muted)}\n.stat .v{font-weight:700;font-size:16px}\n.bar{height:8px;border-radius:999px;background:var(--sunk);overflow:hidden;display:flex}\n.bar > i{display:block;height:100%}\n.bar .b-paid{background:var(--paid)}\n.bar .b-env{background:var(--env)}\n.bar .b-save{background:var(--save)}\n.bar .b-over{background:var(--warn)}\n.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:12px;color:var(--muted)}\n.legend span::before{content:\"\";display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:5px;vertical-align:-1px;background:var(--c)}\n.alert{padding:10px 12px;border-radius:10px;background:var(--warn-soft);color:var(--warn);font-size:14px;font-weight:500}\n.sec-head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;margin-bottom:8px}\n.sec-head .meta{font-size:13px;color:var(--muted)}\n.list{display:flex;flex-direction:column}\n.row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:4px 12px;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}\n.row:last-child{border-bottom:0}\n.row .name{font-weight:600;min-width:0;overflow-wrap:anywhere}\n.row .note{font-size:12px;color:var(--muted)}\n.row .amt{text-align:right;font-weight:600;white-space:nowrap}\n.row .amt .of{display:block;font-weight:400;font-size:12px;color:var(--muted)}\n.row .bar{grid-column:1 / -1;height:6px}\n.row .actions{grid-column:1 / -1;display:flex;gap:8px;flex-wrap:wrap}\n.row.done .name{color:var(--muted)}\n.tags{display:inline-flex;gap:6px;margin-left:6px;vertical-align:1px}\n.btn{border:1px solid var(--line);background:var(--surface);border-radius:10px;padding:9px 14px;font-weight:600;font-size:14px;min-height:40px}\n.btn:hover{border-color:var(--muted)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}\n.btn.paid{background:var(--paid);border-color:var(--paid);color:#fff}\n.btn.save{background:var(--save);border-color:var(--save);color:#fff}\n.btn.ghost{background:transparent}\n.btn.small{min-height:34px;padding:6px 12px;font-size:13px}\n.btn.danger{color:var(--paid)}\n.btn:disabled{opacity:.5;cursor:not-allowed}\n.btn-row{display:flex;flex-wrap:wrap;gap:8px}\n.log .row{grid-template-columns:minmax(0,1fr) auto auto}\n.log .when{font-size:12px;color:var(--muted)}\n.x{border:0;background:transparent;color:var(--muted);font-size:13px;padding:6px 8px;border-radius:8px;min-height:34px}\n.x.armed{background:var(--paid-soft);color:var(--paid);font-weight:600}\n.empty{padding:28px 18px;text-align:center;color:var(--muted);display:flex;flex-direction:column;gap:10px;align-items:center}\n.empty h2{color:var(--ink)}\n/* charts */\n.chart{padding:14px 10px 6px}\n.chart svg{width:100%;height:auto;display:block}\n.chart text{fill:var(--muted);font-family:var(--font-body);font-size:19px}\n.chart .grid{stroke:var(--line);stroke-width:1}\n.chart .ln{stroke:var(--save);stroke-width:2.5;fill:none}\n.chart .ar{fill:var(--save);fill-opacity:.12}\n.chart .dot{fill:var(--surface);stroke:var(--save);stroke-width:2}\n.chart .dot.end{fill:var(--save)}\n.chart .lbl{fill:var(--ink);font-weight:600}\n.chart .bars rect{fill:var(--save)}\n.chart .bars rect.cur{fill:var(--accent)}\ntable.hist{width:100%;border-collapse:collapse;font-size:14px}\n.hist th,.hist td{padding:10px 12px;text-align:right;border-bottom:1px solid var(--line);white-space:nowrap}\n.hist th:first-child,.hist td:first-child{text-align:left}\n.hist th{font-size:12px;color:var(--muted);font-weight:600}\n.hist tr:last-child td{border-bottom:0}\n.hist tr.clickable{cursor:pointer}\n.hist tr.clickable:hover td{background:var(--sunk)}\n.scroll{overflow-x:auto}\n/* tabs */\n.tabs{position:fixed;left:0;right:0;bottom:0;z-index:6;background:var(--surface);border-top:1px solid var(--line);padding-bottom:env(safe-area-inset-bottom,0px)}\n.tabs .wrap{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;padding-block:8px}\n.tabs a{display:flex;flex-direction:column;align-items:center;gap:2px;text-decoration:none;color:var(--muted);font-size:12px;font-weight:600;padding:6px;border-radius:10px}\n.tabs a svg{width:22px;height:22px}\n.tabs a[aria-current=\"page\"]{color:var(--accent);background:var(--accent-soft)}\n/* sheet */\n.backdrop{position:fixed;inset:0;z-index:20;background:rgba(10,16,14,.45);display:flex;align-items:flex-end;justify-content:center}\n.sheet{background:var(--surface);width:100%;max-width:620px;max-height:92vh;overflow:auto;border-radius:16px 16px 0 0;padding:18px max(16px,env(safe-area-inset-left,0px)) calc(18px + env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-right,0px));display:flex;flex-direction:column;gap:14px}\n@media (min-width:700px){.backdrop{align-items:center}.sheet{border-radius:16px}}\n.sheet h2{font-size:20px}\n.sheet .hint{color:var(--muted);font-size:14px}\n.field{display:flex;flex-direction:column;gap:6px}\n.field label{font-size:13px;font-weight:600;color:var(--muted)}\n.input{border:1px solid var(--line);background:var(--bg);border-radius:10px;padding:10px 12px;min-height:44px;width:100%}\n.input.big-in{font-size:24px;font-weight:700;font-family:var(--font-display)}\n.chips{display:flex;flex-wrap:wrap;gap:8px}\n.chip{border:1px solid var(--line);background:var(--sunk);border-radius:999px;padding:6px 12px;font-size:14px;font-weight:600;min-height:36px}\n.err{color:var(--paid);font-size:13px;font-weight:600}\n.err:empty{display:none}\n.plan-row{display:grid;grid-template-columns:minmax(0,1fr) 96px;gap:8px;padding:10px 0;border-bottom:1px solid var(--line)}\n.plan-row .wide{grid-column:1 / -1;display:flex;gap:8px;align-items:center}\n.plan-row select{flex:1;min-width:0}\n.parts-edit{grid-column:1 / -1;display:flex;flex-direction:column;gap:6px;padding-left:12px;border-left:2px solid var(--line)}\n.parts-edit:empty{display:none}\n.part-row{display:grid;grid-template-columns:minmax(0,1fr) 88px auto;gap:6px;align-items:center}\n.plan-row.is-split [data-f=\"planned\"]{background:var(--sunk);color:var(--muted)}\n.parts{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}\n.part{font-size:12px;font-weight:500;color:var(--muted);background:var(--sunk);padding:2px 8px;border-radius:999px}\n.part.done{color:var(--paid);background:var(--paid-soft)}\n.radio{display:flex;gap:10px;align-items:flex-start;padding:8px 0}\n.radio input{margin-top:4px}\n.toast{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(84px + env(safe-area-inset-bottom,0px));z-index:30;background:var(--ink);color:var(--bg);padding:10px 16px;border-radius:10px;font-weight:600;font-size:14px;max-width:calc(100% - 32px)}\n.loading{padding:40px 0;text-align:center;color:var(--muted)}\n@media (prefers-reduced-motion:no-preference){.sheet{animation:up .18s ease-out}@keyframes up{from{transform:translateY(16px);opacity:.6}}}\n@media (max-width:380px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.big{font-size:30px}}\n</style>\n</head>\n<body>\n<header class=\"top\"><div class=\"wrap\">\n<div style=\"min-width:0\">\n<h1 id=\"hdr-title\">Salary Manager</h1>\n<div class=\"sub\" id=\"hdr-sub\">Loading your money\u2026</div>\n</div>\n<span id=\"hdr-pill\"></span>\n</div></header>\n<main class=\"wrap\" id=\"app\">\n<section class=\"view\" id=\"v-month\"><div class=\"loading\">Loading your months\u2026</div></section>\n<section class=\"view\" id=\"v-savings\" hidden></section>\n<section class=\"view\" id=\"v-history\" hidden></section>\n</main>\n<nav class=\"tabs\" aria-label=\"Sections\"><div class=\"wrap\">\n<a href=\"#month\" data-tab=\"month\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"15\" rx=\"2\"/><path d=\"M3 10h18M8 3v4M16 3v4\"/></svg>Month</a>\n<a href=\"#savings\" data-tab=\"savings\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\"><path d=\"M4 19V9M10 19V5M16 19v-7M22 19H2\"/></svg>Savings</a>\n<a href=\"#history\" data-tab=\"history\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" aria-hidden=\"true\"><path d=\"M4 6h16M4 12h16M4 18h10\"/></svg>History</a>\n</div></nav>\n<div class=\"backdrop\" id=\"backdrop\" hidden><div class=\"sheet\" id=\"sheet\" role=\"dialog\" aria-modal=\"true\"></div></div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n<script>\n/* On-phone database: same shape as the online one (doc / collection / onSnapshot / add / set / delete),\nkept in this browser's storage so the app works with no signal. */\nconst LocalDB = (function(){\nconst KEY = \"salary-manager-data-v1\";\nconst load = ()=>{ try{ const v = JSON.parse(localStorage.getItem(KEY) || \"{}\"); return v && typeof v === \"object\" ? v : {}; }catch(e){ return {}; } };\nlet STORE = load();\nconst listeners = new Set();\nconst copy = (o)=>JSON.parse(JSON.stringify(o));\nconst persist = ()=>localStorage.setItem(KEY, JSON.stringify(STORE));\nconst notify = ()=>setTimeout(()=>listeners.forEach(l=>{ try{ l.fire(); }catch(e){ console.error(e); } }),0);\nconst snapDoc = (p)=>({ id:p.split(\"/\").pop(), exists: Object.prototype.hasOwnProperty.call(STORE,p), data:()=> Object.prototype.hasOwnProperty.call(STORE,p) ? copy(STORE[p]) : undefined, metadata:{fromCache:false,hasPendingWrites:false} });\nconst snapCol = (c)=>{ const n=c.split(\"/\").length+1; const docs=Object.keys(STORE).filter(p=>p.startsWith(c+\"/\")&&p.split(\"/\").length===n).sort().map(snapDoc); return {docs,size:docs.length,empty:!docs.length,docChanges:()=>[],metadata:{fromCache:false,hasPendingWrites:false}}; };\nfunction put(p, d){\nconst had = Object.prototype.hasOwnProperty.call(STORE,p), prev = STORE[p];\nif(d===undefined) delete STORE[p]; else STORE[p]=copy(d);\ntry{ persist(); }\ncatch(e){ if(had) STORE[p]=prev; else delete STORE[p]; throw {code:\"quota_exceeded\", message:\"Phone storage is full\"}; }\nnotify();\n}\nconst genId = ()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);\nconst docRef = (p)=>({ id:p.split(\"/\").pop(), path:p,\nget: async()=>snapDoc(p),\nset: async(d)=>put(p,d),\nupdate: async(d)=>{ if(!(p in STORE)) throw {code:\"invalid_argument\"}; put(p,Object.assign(copy(STORE[p]),d)); },\ndelete: async()=>put(p,undefined),\nonSnapshot(cb){ const l={fire:()=>cb(snapDoc(p))}; listeners.add(l); setTimeout(l.fire,0); return ()=>listeners.delete(l); },\ncollection:(c)=>colRef(p+\"/\"+c) });\nconst colRef = (c)=>({ path:c,\ndoc:(id)=>docRef(c+\"/\"+(id||genId())),\nadd: async(d)=>{ const r=docRef(c+\"/\"+genId()); await r.set(d); return r; },\nonSnapshot(cb){ const l={fire:()=>cb(snapCol(c))}; listeners.add(l); setTimeout(l.fire,0); return ()=>listeners.delete(l); } });\n// another tab of the app changed the data\nwindow.addEventListener(\"storage\", e=>{ if(e.key===KEY){ STORE=load(); notify(); } });\nreturn {\ndoc: docRef, collection: colRef,\ndump: ()=>copy(STORE),\nreplaceAll(data){ const prev=STORE; STORE=copy(data); try{ persist(); }catch(e){ STORE=prev; throw {code:\"quota_exceeded\"}; } notify(); },\nisEmpty: ()=>Object.keys(STORE).length===0\n};\n})();\n/* Hand a file to the person: share sheet on phones (Save to Files / Drive / WhatsApp), download elsewhere. */\nasync function saveFile(name, text, mime){\nconst blob = new Blob([text], {type:mime});\ntry{\nconst f = new File([blob], name, {type:mime});\nif(navigator.canShare && navigator.canShare({files:[f]})){ await navigator.share({files:[f], title:name}); return \"shared\"; }\n}catch(e){ if(e && e.name===\"AbortError\") return \"cancelled\"; }\nconst a=document.createElement(\"a\"); a.href=URL.createObjectURL(blob); a.download=name; document.body.appendChild(a); a.click();\nsetTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },1500);\nreturn \"downloaded\";\n}\n</script>\n<script>\n(function(){\n\"use strict\";\nconst CUR = \"DH\";\nconst S = { db:null, dl:null, months:{}, withdrawals:[], savings:[], settings:null,\nready:{m:false,w:false,s:false,t:false}, tab:\"month\", viewKey:null, failed:false };\n/* ---------- helpers ---------- */\nconst $ = (id)=>document.getElementById(id);\nconst esc = (s)=>String(s==null?\"\":s).replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst fmt = (n)=>{ const v=Math.round((Number(n)||0)*100)/100; return v.toLocaleString(\"en-US\",{maximumFractionDigits:2}); };\nconst money = (n)=>fmt(n)+\" \"+CUR;\nconst num = (v)=>{ const n=parseFloat(String(v).replace(/\\s/g,\"\").replace(\",\",\".\")); return isFinite(n)?n:NaN; };\nconst uid = ()=>Math.random().toString(36).slice(2,10);\nconst sum = (arr,f)=>arr.reduce((a,x)=>a+(f?f(x):x),0);\nfunction monthLabel(key){ const [y,m]=key.split(\"-\").map(Number); return new Date(y,m-1,1).toLocaleString(\"en-GB\",{month:\"long\",year:\"numeric\"}); }\nfunction monthShort(key){ const [y,m]=key.split(\"-\").map(Number); return new Date(y,m-1,1).toLocaleString(\"en-GB\",{month:\"short\"}); }\nfunction addMonths(key,n){ const [y,m]=key.split(\"-\").map(Number); const d=new Date(y,m-1+n,1); return d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\"); }\nfunction whenText(iso){ if(!iso) return \"Date not recorded\"; const d=new Date(iso); return d.toLocaleString(\"en-GB\",{weekday:\"short\",day:\"numeric\",month:\"short\",hour:\"2-digit\",minute:\"2-digit\"}); }\nfunction localNow(){ const d=new Date(); d.setMinutes(d.getMinutes()-d.getTimezoneOffset()); return d.toISOString().slice(0,16); }\nfunction sortedKeys(){ return Object.keys(S.months).sort(); }\nfunction currentKey(){ const k=S.settings&&S.settings.currentMonth; if(k&&S.months[k]) return k; const ks=sortedKeys(); return ks[ks.length-1]||null; }\nlet toastT=null;\nfunction toast(msg){ const t=$(\"toast\"); t.textContent=msg; t.hidden=false; clearTimeout(toastT); toastT=setTimeout(()=>t.hidden=true,2600); }\n/* ---------- money maths (one place) ---------- */\nfunction calc(key){\nconst m=S.months[key]; if(!m) return null;\nconst charges=m.charges||[];\nconst W=S.withdrawals.filter(w=>w.month===key);\nconst SV=S.savings.filter(e=>e.month===key);\nconst incomeSum=sum(m.income||[],i=>Number(i.amount)||0);\nconst fromSavings=-sum(SV.filter(e=>e.kind===\"withdraw\"),e=>Number(e.amount)||0);\nconst available=(Number(m.salary)||0)+incomeSum+fromSavings;\nconst planned=sum(charges,c=>Number(c.planned)||0);\nconst rows=charges.map(c=>{\nlet taken;\nif(m.imported) taken=Number(c.planned)||0;\nelse if(c.type===\"savings\") taken=sum(SV.filter(e=>e.kind===\"deposit\"&&e.chargeId===c.id),e=>Number(e.amount)||0);\nelse taken=sum(W.filter(w=>w.chargeId===c.id),w=>Number(w.amount)||0);\n// a split charge (e.g. Rent & bills = Rent + Electricity bill): one bar, each part withdrawn on its own\nconst parts=(c.parts&&c.parts.length&&c.type!==\"savings\")?c.parts.map(pt=>{\nconst pp=Number(pt.planned)||0;\nconst t=m.imported?pp:sum(W.filter(w=>w.chargeId===c.id&&w.partId===pt.id),w=>Number(w.amount)||0);\nreturn {...pt, planned:pp, taken:t, left:Math.max(pp-t,0), over:Math.max(t-pp,0), done: pp>0 ? t>=pp : t>0};\n}):null;\nconst p=parts?sum(parts,x=>x.planned):(Number(c.planned)||0);\nreturn {...c, parts, planned:p, taken, left:Math.max(p-taken,0), over:Math.max(taken-p,0), done: p>0 ? taken>=p : taken>0};\n});\nconst unplanned=W.filter(w=>!w.chargeId||!charges.some(c=>c.id===w.chargeId));\nconst unplannedSum=sum(unplanned,w=>Number(w.amount)||0);\nconst savedDeposits=sum(SV.filter(e=>e.kind===\"deposit\"),e=>Number(e.amount)||0);\n// manual \"Add to savings\" from this month's money also leaves the bank; leftovers carried from last month do not\nconst looseDeposits=m.imported?0:sum(SV.filter(e=>e.kind===\"deposit\"&&!e.fromLeftover&&!charges.some(c=>c.id===e.chargeId&&c.type===\"savings\")),e=>Number(e.amount)||0);\nconst takenTotal=sum(rows,r=>r.taken)+unplannedSum+looseDeposits;\nconst leftToTake=sum(rows,r=>r.left);\nreturn { m, rows, W, SV, incomeSum, fromSavings, available, planned, unplanned, unplannedSum,\ntakenTotal, leftToTake, inBank: available-takenTotal, overPlan: planned-available, spare: available-planned-unplannedSum,\nsaved: savedDeposits };\n}\nfunction savingsBalance(uptoKey){ return sum(S.savings.filter(e=>!uptoKey||e.month<=uptoKey),e=>Number(e.amount)||0); }\n/* ---------- database ---------- */\nasync function boot(){\nbindTabs(); route();\nS.db = LocalDB; S.dl = true;\ntry{ if(navigator.storage && navigator.storage.persist) navigator.storage.persist(); }catch(e){}\nconst db = S.db;\nconst err=(e)=>{ console.error(e); toast(\"Couldn't read the data on this phone.\"); };\ndb.collection(\"months\").onSnapshot(snap=>{ const o={}; snap.docs.forEach(d=>{o[d.id]=d.data();}); S.months=o; S.ready.m=true; render(); }, err);\ndb.collection(\"withdrawals\").onSnapshot(snap=>{ S.withdrawals=snap.docs.map(d=>({id:d.id,...d.data()})); S.ready.w=true; render(); }, err);\ndb.collection(\"savings\").onSnapshot(snap=>{ S.savings=snap.docs.map(d=>({id:d.id,...d.data()})); S.ready.s=true; render(); }, err);\ndb.doc(\"settings/app\").onSnapshot(snap=>{ S.settings=snap.exists?snap.data():null; S.ready.t=true; render(); }, err);\nif(\"serviceWorker\" in navigator && location.protocol!==\"file:\"){\nconst hadController = !!navigator.serviceWorker.controller;\nnavigator.serviceWorker.register(\"sw.js\").then(reg=>{\n// check for a newer version every time the app opens with signal, and when signal comes back\nconst check=()=>{ if(navigator.onLine) reg.update().catch(()=>{}); };\ncheck(); window.addEventListener(\"online\", check);\n}).catch(e=>console.warn(\"offline cache not installed\", e));\n// a new version finished installing: show it now, unless a form is open\nnavigator.serviceWorker.addEventListener(\"controllerchange\", ()=>{\nif(!hadController || S.reloading) return;\nif($(\"backdrop\").hidden){ S.reloading=true; location.reload(); }\n});\n}\n}\nasync function write(fn, okMsg){\ntry{ await fn(); if(okMsg) toast(okMsg); return true; }\ncatch(e){ console.error(e); toast(e&&e.code===\"quota_exceeded\" ? \"Storage is full. Export to CSV and remove old entries.\" : \"Not saved. Check your connection and try again.\"); return false; }\n}\n/* ---------- routing ---------- */\nfunction bindTabs(){ window.addEventListener(\"hashchange\",route); }\nfunction route(){\nconst h=(location.hash||\"#month\").slice(1);\nS.tab=[\"month\",\"savings\",\"history\"].includes(h)?h:\"month\";\ndocument.querySelectorAll(\".tabs a\").forEach(a=>a.setAttribute(\"aria-current\",a.dataset.tab===S.tab?\"page\":\"false\"));\n[\"month\",\"savings\",\"history\"].forEach(t=>$(\"v-\"+t).hidden=(t!==S.tab));\nrender();\n}\n/* ---------- render ---------- */\nfunction allReady(){ return S.ready.m&&S.ready.w&&S.ready.s&&S.ready.t; }\nfunction render(){\nif(S.failed){\n$(\"hdr-sub\").textContent=\"Open this page in Claude to load your data.\";\n$(\"v-month\").innerHTML='<div class=\"card empty\"><h2>Your data isn\u2019t reachable here</h2><p>Open Salary Manager from your Claude artifacts while signed in.</p></div>';\nreturn;\n}\nif(!allReady()) return;\nconst cur=currentKey();\n// a month just created may arrive from the store a moment after we asked to show it\nif(S.pendingKey&&S.months[S.pendingKey]){ S.viewKey=S.pendingKey; S.pendingKey=null; }\nif(!S.viewKey||!S.months[S.viewKey]) S.viewKey=cur;\nrenderHeader();\nif(S.tab===\"month\") renderMonth();\nif(S.tab===\"savings\") renderSavings();\nif(S.tab===\"history\") renderHistory();\n}\nfunction renderHeader(){\nconst k=S.viewKey;\nif(!k){ $(\"hdr-title\").textContent=\"Salary Manager\"; $(\"hdr-sub\").textContent=\"No months yet\"; $(\"hdr-pill\").innerHTML=\"\"; return; }\nconst m=S.months[k];\n$(\"hdr-title\").textContent=monthLabel(k);\n$(\"hdr-sub\").textContent=m.salaryOf?(\"Salary of \"+m.salaryOf):\"\";\nconst cur=currentKey();\n$(\"hdr-pill\").innerHTML = k===cur ? '<span class=\"pill open\">Current month</span>'\n: (m.imported?'<span class=\"pill\">From your sheet</span>':'<span class=\"pill\">Closed</span>');\n}\nfunction typeTag(t){\nif(t===\"envelope\") return '<span class=\"pill env\">Envelope</span>';\nif(t===\"savings\") return '<span class=\"pill save\">Savings</span>';\nreturn \"\";\n}\nfunction chargeBar(r){\nconst p=Math.max(r.planned,r.taken,1);\nconst cls=r.type===\"savings\"?\"b-save\":(r.type===\"envelope\"?\"b-env\":\"b-paid\");\nconst inPlan=Math.min(r.taken,r.planned);\nreturn '<div class=\"bar\" aria-hidden=\"true\"><i class=\"'+cls+'\" style=\"width:'+(inPlan/p*100)+'%\"></i>'+(r.over?'<i class=\"b-over\" style=\"width:'+(r.over/p*100)+'%\"></i>':\"\")+'</div>';\n}\nfunction renderMonth(){\nconst el=$(\"v-month\"); const k=S.viewKey;\nif(!k){\nel.innerHTML='<div class=\"card empty\"><h2>Start your first month</h2><p>Enter your salary and the charges you plan for. Each withdrawal is then one tap.</p><div class=\"btn-row\" style=\"justify-content:center\"><button class=\"btn primary\" data-act=\"import\">Restore a backup</button><button class=\"btn\" data-act=\"new-month\">Start fresh</button></div></div>';\nbind(el); return;\n}\nconst c=calc(k); const m=c.m; const cur=currentKey(); const isCur=(k===cur);\nlet h=\"\";\nif(!isCur) h+='<div class=\"btn-row\"><button class=\"btn small\" data-act=\"go-current\">\u2190 Back to '+esc(monthLabel(cur))+'</button></div>';\nif(m.imported) h+='<div class=\"alert\">This month was imported from your sheet. It shows the plan only; the sheet didn\u2019t record each withdrawal.</div>';\n// summary\nconst takenPaid=sum(c.rows.filter(r=>r.type!==\"envelope\"&&r.type!==\"savings\"),r=>Math.min(r.taken,r.planned))+c.unplannedSum;\nconst takenEnv=sum(c.rows.filter(r=>r.type===\"envelope\"),r=>Math.min(r.taken,r.planned));\nconst takenSave=sum(c.rows.filter(r=>r.type===\"savings\"),r=>Math.min(r.taken,r.planned));\nconst overAll=sum(c.rows,r=>r.over);\nconst base=Math.max(c.planned+c.unplannedSum+overAll,1);\nh+='<div class=\"card summary\">'+\n'<div><div class=\"big-label\">Left to withdraw</div><div class=\"big\">'+fmt(c.leftToTake)+'<small>'+CUR+'</small></div></div>'+\n'<div class=\"bar\" style=\"height:10px\" role=\"img\" aria-label=\"'+fmt(c.takenTotal)+' of '+fmt(c.planned)+' withdrawn\">'+\n'<i class=\"b-paid\" style=\"width:'+(takenPaid/base*100)+'%\"></i><i class=\"b-env\" style=\"width:'+(takenEnv/base*100)+'%\"></i><i class=\"b-save\" style=\"width:'+(takenSave/base*100)+'%\"></i><i class=\"b-over\" style=\"width:'+(overAll/base*100)+'%\"></i></div>'+\n'<div class=\"legend\"><span style=\"--c:var(--paid)\">Withdrawn</span><span style=\"--c:var(--env)\">Envelopes</span><span style=\"--c:var(--save)\">To savings</span>'+(overAll?'<span style=\"--c:var(--warn)\">Over plan</span>':'')+'</div>'+\n'<div class=\"stats\">'+\n'<div class=\"stat\"><div class=\"k\">Money in</div><div class=\"v\">'+money(c.available)+'</div></div>'+\n'<div class=\"stat\"><div class=\"k\">Planned</div><div class=\"v\">'+money(c.planned)+'</div></div>'+\n'<div class=\"stat\"><div class=\"k\">Withdrawn</div><div class=\"v\">'+money(c.takenTotal)+'</div></div>'+\n'</div>';\nif(c.overPlan>0) h+='<div class=\"alert\">Your plan is '+money(c.overPlan)+' over your money in.'+(c.unplannedSum?' Unplanned withdrawals add '+money(c.unplannedSum)+' more.':'')+'</div>';\nelse if(!m.imported&&c.spare<0) h+='<div class=\"alert\">Unplanned withdrawals ('+money(c.unplannedSum)+') are '+money(-c.spare)+' more than your spare money. That amount now comes from your planned charges.</div>';\nelse if(!m.imported) h+='<div class=\"hint\" style=\"font-size:13px;color:var(--muted)\">Not planned yet: '+money(c.spare)+(c.unplannedSum?' (after '+money(c.unplannedSum)+' unplanned)':'')+' \u00b7 Still in the bank: '+money(c.inBank)+'</div>';\nh+='</div>';\nif(!m.imported){\nh+='<div class=\"btn-row\"><button class=\"btn\" data-act=\"unplanned\">+ Unplanned withdrawal</button><button class=\"btn\" data-act=\"income\">+ Extra income</button><button class=\"btn\" data-act=\"edit-plan\">Edit plan</button></div>';\n}\n// to withdraw / done\nconst todo=c.rows.filter(r=>!r.done&&!m.imported), done=c.rows.filter(r=>r.done||m.imported);\nif(todo.length){\nh+='<div><div class=\"sec-head\"><h2>Still to withdraw</h2><span class=\"meta\">'+todo.length+' left</span></div><div class=\"card list\">'+\ntodo.map(r=>{\nconst act=r.type===\"savings\"\n? '<button class=\"btn small save\" data-act=\"withdraw\" data-id=\"'+esc(r.id)+'\">Move to savings</button>'\n: r.parts\n? r.parts.filter(pt=>!pt.done).map(pt=>'<button class=\"btn small '+(r.type===\"envelope\"?\"\":\"paid\")+'\" data-act=\"withdraw\" data-id=\"'+esc(r.id)+'\" data-part=\"'+esc(pt.id)+'\">'+esc(pt.name)+' '+fmt(pt.left)+'</button>').join(\"\")\n: '<button class=\"btn small '+(r.type===\"envelope\"?\"\":\"paid\")+'\" data-act=\"withdraw\" data-id=\"'+esc(r.id)+'\">'+(r.type===\"envelope\"?\"Take some\":\"Withdraw \"+fmt(r.left))+'</button>';\nreturn '<div class=\"row\"><div class=\"name\">'+esc(r.name)+'<span class=\"tags\">'+typeTag(r.type)+'</span>'+(r.note?'<div class=\"note\">'+esc(r.note)+'</div>':'')+partsLine(r)+'</div>'+\n'<div class=\"amt\">'+fmt(r.left)+' left<span class=\"of\">'+fmt(r.taken)+' of '+fmt(r.planned)+'</span></div>'+chargeBar(r)+'<div class=\"actions\">'+act+'</div></div>';\n}).join(\"\")+'</div></div>';\n} else if(!m.imported && c.rows.length){\nh+='<div class=\"card empty\"><h2>Everything is withdrawn</h2><p>Every charge for this month is covered.</p></div>';\n}\nif(done.length){\nh+='<div><div class=\"sec-head\"><h2>'+(m.imported?\"Plan\":\"Done\")+'</h2><span class=\"meta\">'+money(sum(done,r=>r.taken))+'</span></div><div class=\"card list\">'+\ndone.map(r=>'<div class=\"row done\"><div class=\"name\">'+esc(r.name)+'<span class=\"tags\">'+(m.imported?typeTag(r.type):(r.type===\"savings\"?'<span class=\"pill save\">Saved</span>':'<span class=\"pill paid\">Withdrawn</span>'))+(r.over?'<span class=\"pill warn\">+'+fmt(r.over)+' over</span>':'')+'</span>'+partsLine(r)+'</div>'+\n'<div class=\"amt\">'+fmt(r.taken)+'<span class=\"of\">planned '+fmt(r.planned)+'</span></div>'+\n(!m.imported&&r.type===\"envelope\"&&!r.parts?'<div class=\"actions\"><button class=\"btn small ghost\" data-act=\"withdraw\" data-id=\"'+esc(r.id)+'\">Take more</button></div>':'')+'</div>').join(\"\")+'</div></div>';\n}\n// extra income\nif((m.income||[]).length){\nh+='<div><div class=\"sec-head\"><h2>Extra income</h2><span class=\"meta\">'+money(c.incomeSum)+'</span></div><div class=\"card list\">'+\nm.income.map(i=>'<div class=\"row\"><div class=\"name\">'+esc(i.name)+'</div><div class=\"amt\">+'+fmt(i.amount)+'</div>'+(!m.imported?'<div class=\"actions\"><button class=\"x\" data-act=\"del-income\" data-id=\"'+esc(i.id)+'\">Remove</button></div>':'')+'</div>').join(\"\")+'</div></div>';\n}\n// log\nif(!m.imported){\nconst log=[...c.W.map(w=>({kind:\"w\",id:w.id,at:w.at,imported:w.imported,amount:w.amount,note:w.note,label:labelFor(m,w.chargeId,w.note,w.partId)})),\n...c.SV.map(e=>({kind:\"s\",id:e.id,at:e.at,imported:e.imported,amount:e.amount,note:e.reason,label:e.kind===\"deposit\"?\"To savings\":(e.kind===\"withdraw\"?\"From savings\":\"Savings correction\")}))]\n.sort((a,b)=>String(b.at||\"\").localeCompare(String(a.at||\"\")));\nh+='<div><div class=\"sec-head\"><h2>Withdrawal log</h2><span class=\"meta\">'+log.length+' entries</span></div>';\nif(!log.length) h+='<div class=\"card empty\"><p>No withdrawals yet. Tap a charge above when you take money out.</p></div>';\nelse h+='<div class=\"card list log\">'+log.map(x=>'<div class=\"row\"><div><div class=\"name\">'+esc(x.label)+'</div><div class=\"when\">'+esc(x.at?whenText(x.at):(x.imported?\"From your sheet \\u00b7 date not recorded\":\"Date not recorded\"))+(x.note&&x.kind===\"w\"&&x.label.indexOf(x.note)<0?' \u00b7 '+esc(x.note):'')+(x.note&&x.kind===\"s\"?' \u00b7 '+esc(x.note):'')+'</div></div>'+\n'<div class=\"amt\" style=\"color:'+(x.kind===\"s\"&&x.amount>0?\"var(--save)\":\"var(--paid)\")+'\">'+(x.kind===\"s\"?(x.amount>0?\"+\":\"\u2212\")+fmt(Math.abs(x.amount)):\"\u2212\"+fmt(x.amount))+'</div>'+\n'<button class=\"x\" data-act=\"del-entry\" data-kind=\"'+x.kind+'\" data-id=\"'+esc(x.id)+'\" aria-label=\"Delete entry\">Delete</button></div>').join(\"\")+'</div>';\nh+='</div>';\n}\nif(isCur&&backupDue()) h+='<div class=\"alert\" style=\"display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap\"><span>'+(S.settings&&S.settings.lastBackupAt?'Your last backup is over 2 weeks old.':'You haven\\u2019t saved a backup yet.')+' Data lives only on this phone.</span><button class=\"btn small\" data-act=\"backup\">Save backup</button></div>';\nif(isCur&&!m.imported) h+='<div class=\"card summary\"><div><h2>Month finished?</h2><p class=\"hint\" style=\"color:var(--muted);margin:6px 0 0\">Start '+esc(monthLabel(addMonths(k,1)))+' with the same charges. You can change amounts before saving.</p></div><div class=\"btn-row\"><button class=\"btn primary\" data-act=\"new-month\">Start '+esc(monthLabel(addMonths(k,1)))+'</button></div></div>';\nel.innerHTML=h; bind(el);\n}\nfunction labelFor(m,chargeId,note,partId){\nconst ch=(m.charges||[]).find(c=>c.id===chargeId);\nif(!ch) return \"Unplanned\"+(note?\": \"+note:\"\");\nconst pt=partId&&ch.parts?ch.parts.find(x=>x.id===partId):null;\nreturn ch.name+(pt?\" \\u00b7 \"+pt.name:\"\");\n}\nfunction partsLine(r){\nif(!r.parts) return \"\";\nreturn '<div class=\"parts\">'+r.parts.map(pt=>'<span class=\"part'+(pt.done?' done':'')+'\">'+esc(pt.name)+' '+(pt.done?'\\u2713 '+fmt(pt.taken):fmt(pt.left)+' left')+'</span>').join(\"\")+'</div>';\n}\n/* ---------- savings view ---------- */\nfunction renderSavings(){\nconst el=$(\"v-savings\"); const keys=sortedKeys();\nconst bal=savingsBalance();\nconst cur=currentKey();\nconst cc=cur?calc(cur):null;\nconst rates=keys.map(k=>{const c=calc(k); return {k, saved:c.saved, salary:Number(c.m.salary)||0};});\nconst withSalary=rates.filter(r=>r.salary>0);\nconst avgRate=withSalary.length?sum(withSalary,r=>r.saved/r.salary)/withSalary.length:0;\nlet h='<div class=\"card summary\"><div><div class=\"big-label\">Savings balance</div><div class=\"big\">'+fmt(bal)+'<small>'+CUR+'</small></div></div>'+\n'<div class=\"stats\">'+\n'<div class=\"stat\"><div class=\"k\">Saved this month</div><div class=\"v\">'+money(cc?cc.saved:0)+'</div></div>'+\n'<div class=\"stat\"><div class=\"k\">Of salary</div><div class=\"v\">'+(cc&&cc.m.salary?Math.round(cc.saved/cc.m.salary*100):0)+'%</div></div>'+\n'<div class=\"stat\"><div class=\"k\">Average rate</div><div class=\"v\">'+Math.round(avgRate*100)+'%</div></div>'+\n'</div><div class=\"btn-row\"><button class=\"btn save\" data-act=\"sav-in\">+ Add to savings</button><button class=\"btn\" data-act=\"sav-out\">Take out</button></div></div>';\nif(keys.length){\nh+='<div><div class=\"sec-head\"><h2>Balance by month</h2><span class=\"meta\">End of each month</span></div><div class=\"card chart\">'+lineChart(keys.map(k=>({label:monthShort(k),value:savingsBalance(k)})))+'</div></div>';\nh+='<div><div class=\"sec-head\"><h2>Saved each month</h2><span class=\"meta\">% of salary under each bar</span></div><div class=\"card chart\">'+barChart(rates.map(r=>({label:monthShort(r.k),value:r.saved,sub:r.salary?Math.round(r.saved/r.salary*100)+\"%\":\"\",cur:r.k===cur})))+'</div></div>';\n}\nconst led=[...S.savings].sort((a,b)=>(b.month+(b.at||\"\")).localeCompare(a.month+(a.at||\"\")));\nh+='<div><div class=\"sec-head\"><h2>Savings log</h2><span class=\"meta\">Every change has a reason</span></div>';\nif(!led.length) h+='<div class=\"card empty\"><p>No savings entries yet.</p></div>';\nelse h+='<div class=\"card list log\">'+led.map(e=>'<div class=\"row\"><div><div class=\"name\">'+esc(e.reason||(e.kind===\"deposit\"?\"Savings\":\"Change\"))+'</div><div class=\"when\">'+esc(monthLabel(e.month))+' \u00b7 '+esc(e.at?whenText(e.at):\"from your sheet\")+'</div></div>'+\n'<div class=\"amt\" style=\"color:'+(e.amount>=0?\"var(--save)\":\"var(--paid)\")+'\">'+(e.amount>=0?\"+\":\"\u2212\")+fmt(Math.abs(e.amount))+'</div>'+\n'<button class=\"x\" data-act=\"del-entry\" data-kind=\"s\" data-id=\"'+esc(e.id)+'\" aria-label=\"Delete entry\">Delete</button></div>').join(\"\")+'</div>';\nh+='</div>';\nel.innerHTML=h; bind(el);\n}\n/* ---------- history view ---------- */\nfunction renderHistory(){\nconst el=$(\"v-history\"); const keys=sortedKeys().reverse(); const cur=currentKey();\nlet h='<div><div class=\"sec-head\"><h2>All months</h2><span class=\"meta\">Tap a month to open it</span></div>';\nif(!keys.length) h+='<div class=\"card empty\"><p>No months yet.</p></div>';\nelse{\nh+='<div class=\"card scroll\"><table class=\"hist\"><thead><tr><th>Month</th><th>Money in</th><th>Planned</th><th>Saved</th><th>Savings</th></tr></thead><tbody>'+\nkeys.map(k=>{const c=calc(k); return '<tr class=\"clickable\" data-act=\"open-month\" data-id=\"'+k+'\" tabindex=\"0\"><td><strong>'+esc(monthShort(k)+\" \"+k.slice(0,4))+'</strong>'+(k===cur?' <span class=\"pill open\">Now</span>':'')+'</td><td>'+fmt(c.available)+'</td><td>'+fmt(c.planned)+'</td><td>'+fmt(c.saved)+'</td><td>'+fmt(savingsBalance(k))+'</td></tr>';}).join(\"\")+\n'</tbody></table></div>';\n}\nh+='</div>';\nconst lb=S.settings&&S.settings.lastBackupAt;\nh+='<div class=\"card summary\"><div><h2>Backup</h2><p style=\"color:var(--muted);margin:6px 0 0\">Your money data is saved only on this phone. Save a backup now and then and keep it in Google Drive or WhatsApp. On a new phone, tap Restore backup.</p>'+\n'<p style=\"margin:8px 0 0;font-size:13px;font-weight:600;color:'+(backupDue()?\"var(--warn)\":\"var(--muted)\")+'\">'+(lb?\"Last backup: \"+esc(new Date(lb).toLocaleDateString(\"en-GB\",{day:\"numeric\",month:\"short\",year:\"numeric\"})):\"No backup saved yet\")+'</p></div>'+\n'<div class=\"btn-row\"><button class=\"btn primary\" data-act=\"backup\">Save backup</button><button class=\"btn\" data-act=\"import\">Restore backup</button><button class=\"btn\" data-act=\"export\">Export to CSV</button></div>'+\n'<p style=\"margin:0;font-size:12px;color:var(--muted)\">Works offline \\u00b7 version 1.0.4</p></div>';\nel.innerHTML=h; bind(el);\n}\nfunction backupDue(){ const lb=S.settings&&S.settings.lastBackupAt; return !lb || (Date.now()-new Date(lb).getTime()) > 14*864e5; }\n/* ---------- charts ---------- */\nfunction niceMax(v){ if(v<=0) return 100; const p=Math.pow(10,Math.floor(Math.log10(v))); const n=v/p; const s=n<=1?1:n<=2?2:n<=2.5?2.5:n<=5?5:10; return s*p; }\nfunction lineChart(pts){\nconst W=600,H=260,L=62,R=24,T=36,B=40; const max=niceMax(Math.max(...pts.map(p=>p.value),1));\nconst x=i=>pts.length===1?(L+(W-L-R)/2):L+i*(W-L-R)/(pts.length-1); const y=v=>T+(H-T-B)*(1-v/max);\nlet g=\"\"; for(let i=0;i<=4;i++){const v=max*i/4; g+='<line class=\"grid\" x1=\"'+L+'\" x2=\"'+(W-R)+'\" y1=\"'+y(v)+'\" y2=\"'+y(v)+'\"/><text x=\"'+(L-8)+'\" y=\"'+(y(v)+4)+'\" text-anchor=\"end\">'+fmtK(v)+'</text>';}\nconst d=pts.map((p,i)=>(i?\"L\":\"M\")+x(i).toFixed(1)+\" \"+y(p.value).toFixed(1)).join(\" \");\nconst area=d+\" L\"+x(pts.length-1).toFixed(1)+\" \"+y(0)+\" L\"+x(0).toFixed(1)+\" \"+y(0)+\" Z\";\nconst dots=pts.map((p,i)=>'<circle class=\"dot'+(i===pts.length-1?\" end\":\"\")+'\" cx=\"'+x(i)+'\" cy=\"'+y(p.value)+'\" r=\"'+(i===pts.length-1?5:3.5)+'\"/><text x=\"'+x(i)+'\" y=\"'+(H-10)+'\" text-anchor=\"middle\">'+esc(p.label)+'</text>').join(\"\");\nconst last=pts[pts.length-1]; const lx=x(pts.length-1);\nconst lbl='<text class=\"lbl\" x=\"'+Math.min(lx,W-R)+'\" y=\"'+(y(last.value)-12)+'\" text-anchor=\"end\">'+fmt(last.value)+'</text>';\nreturn '<svg viewBox=\"0 0 '+W+' '+H+'\" role=\"img\" aria-label=\"Savings balance by month\">'+g+'<path class=\"ar\" d=\"'+area+'\"/><path class=\"ln\" d=\"'+d+'\"/>'+dots+lbl+'</svg>';\n}\nfunction barChart(pts){\nconst W=600,H=270,L=62,R=12,T=34,B=64; const max=niceMax(Math.max(...pts.map(p=>p.value),1));\nconst slot=(W-L-R)/pts.length; const bw=Math.min(46,slot*.6); const y=v=>T+(H-T-B)*(1-v/max);\nlet g=\"\"; for(let i=0;i<=4;i++){const v=max*i/4; g+='<line class=\"grid\" x1=\"'+L+'\" x2=\"'+(W-R)+'\" y1=\"'+y(v)+'\" y2=\"'+y(v)+'\"/><text x=\"'+(L-8)+'\" y=\"'+(y(v)+4)+'\" text-anchor=\"end\">'+fmtK(v)+'</text>';}\nconst bars=pts.map((p,i)=>{const cx=L+slot*i+slot/2; const top=y(Math.max(p.value,0)); return '<rect class=\"'+(p.cur?\"cur\":\"\")+'\" x=\"'+(cx-bw/2)+'\" y=\"'+top+'\" width=\"'+bw+'\" height=\"'+Math.max(y(0)-top,0)+'\" rx=\"3\"/>'+\n'<text class=\"lbl\" x=\"'+cx+'\" y=\"'+(top-8)+'\" text-anchor=\"middle\">'+fmtK(p.value)+'</text><text x=\"'+cx+'\" y=\"'+(H-36)+'\" text-anchor=\"middle\">'+esc(p.label)+'</text><text x=\"'+cx+'\" y=\"'+(H-8)+'\" text-anchor=\"middle\">'+esc(p.sub)+'</text>';}).join(\"\");\nreturn '<svg viewBox=\"0 0 '+W+' '+H+'\" role=\"img\" aria-label=\"Amount saved each month\"><g>'+g+'</g><g class=\"bars\">'+bars+'</g></svg>';\n}\nfunction fmtK(v){ return v>=1000?(Math.round(v/100)/10)+\"k\":String(Math.round(v)); }\n/* ---------- actions ---------- */\nfunction bind(root){\nroot.querySelectorAll(\"[data-act]\").forEach(b=>{\nb.addEventListener(\"click\",()=>act(b.dataset.act,b.dataset.id,b));\nif(b.tagName===\"TR\") b.addEventListener(\"keydown\",e=>{ if(e.key===\"Enter\") act(b.dataset.act,b.dataset.id,b); });\n});\n}\nfunction act(a,id,btn){\nconst k=S.viewKey;\nif(a===\"withdraw\") return sheetWithdraw(k,id,btn&&btn.dataset.part);\nif(a===\"unplanned\") return sheetUnplanned(k);\nif(a===\"income\") return sheetIncome(k);\nif(a===\"edit-plan\") return sheetPlan(k);\nif(a===\"new-month\") return sheetNewMonth();\nif(a===\"sav-in\") return sheetSavings(\"in\");\nif(a===\"sav-out\") return sheetSavings(\"out\");\nif(a===\"go-current\"){ S.viewKey=currentKey(); render(); return; }\nif(a===\"open-month\"){ S.viewKey=id; location.hash=\"#month\"; route(); window.scrollTo(0,0); return; }\nif(a===\"export\") return exportCsv();\nif(a===\"backup\") return exportBackup();\nif(a===\"import\") return sheetImport();\nif(a===\"del-entry\"||a===\"del-income\") return armDelete(btn, async()=>{\nif(a===\"del-income\"){ const m=clone(S.months[k]); m.income=(m.income||[]).filter(i=>i.id!==id); await write(()=>S.db.doc(\"months/\"+k).set(m),\"Income removed\"); }\nelse await write(()=>S.db.doc((btn.dataset.kind===\"s\"?\"savings/\":\"withdrawals/\")+id).delete(),\"Entry deleted\");\n});\n}\nfunction armDelete(btn,fn){\nif(btn.classList.contains(\"armed\")){ btn.disabled=true; fn(); return; }\nconst old=btn.textContent; btn.classList.add(\"armed\"); btn.textContent=\"Tap again\";\nsetTimeout(()=>{ if(btn.isConnected){ btn.classList.remove(\"armed\"); btn.textContent=old; } },3000);\n}\nconst clone=(o)=>JSON.parse(JSON.stringify(o));\n/* ---------- sheet plumbing ---------- */\nfunction openSheet(html,onReady){\nconst sh=$(\"sheet\"); sh.innerHTML=html; $(\"backdrop\").hidden=false;\nsh.querySelectorAll(\"[data-close]\").forEach(b=>b.addEventListener(\"click\",closeSheet));\nif(onReady) onReady(sh);\nconst f=sh.querySelector(\"input,select\"); if(f) setTimeout(()=>f.focus(),30);\n}\nfunction closeSheet(){ $(\"backdrop\").hidden=true; $(\"sheet\").innerHTML=\"\"; }\n$(\"backdrop\").addEventListener(\"click\",e=>{ if(e.target===$(\"backdrop\")) closeSheet(); });\ndocument.addEventListener(\"keydown\",e=>{ if(e.key===\"Escape\"&&!$(\"backdrop\").hidden) closeSheet(); });\nfunction dateField(id){ return '<div class=\"field\"><label for=\"'+id+'\">When</label><input class=\"input\" type=\"datetime-local\" id=\"'+id+'\" value=\"'+localNow()+'\"></div>'; }\nfunction readDate(id){ const v=$(id).value; const d=v?new Date(v):new Date(); return isNaN(d)?new Date().toISOString():d.toISOString(); }\nfunction sheetWithdraw(k,chargeId,partId){\nconst c=calc(k); const r=c.rows.find(x=>x.id===chargeId); if(!r) return;\nconst pt=partId&&r.parts?r.parts.find(x=>x.id===partId):null;\nif(r.parts&&!pt) return;\nconst t=pt||r;\nconst isSave=r.type===\"savings\";\nconst chips=r.type===\"envelope\"?[50,100,200].filter(v=>v<=Math.max(t.left,200)):[];\nopenSheet(\n'<h2>'+(isSave?\"Move to savings\":\"Withdraw\")+' \u00b7 '+esc(r.name)+(pt?' \\u2014 '+esc(pt.name):'')+'</h2>'+\n'<p class=\"hint\">'+fmt(t.taken)+' of '+fmt(t.planned)+' '+CUR+' taken. '+fmt(t.left)+' '+CUR+' left.</p>'+\n'<div class=\"field\"><label for=\"w-amt\">Amount ('+CUR+')</label><input class=\"input big-in\" id=\"w-amt\" inputmode=\"decimal\" autocomplete=\"off\" value=\"'+(r.type===\"envelope\"?\"\":(t.left||\"\"))+'\"></div>'+\n'<div class=\"chips\">'+chips.map(v=>'<button class=\"chip\" data-chip=\"'+v+'\">'+v+'</button>').join(\"\")+(t.left?'<button class=\"chip\" data-chip=\"'+t.left+'\">All left ('+fmt(t.left)+')</button>':'')+'</div>'+\ndateField(\"w-at\")+\n'<div class=\"field\"><label for=\"w-note\">Note (optional)</label><input class=\"input\" id=\"w-note\" autocomplete=\"off\" placeholder=\"'+(isSave?\"e.g. salary day\":\"e.g. second gaz top-up\")+'\"></div>'+\n'<div class=\"err\" id=\"w-err\"></div>'+\n'<div class=\"btn-row\"><button class=\"btn '+(isSave?\"save\":\"paid\")+'\" id=\"w-go\">'+(isSave?\"Move to savings\":\"Record withdrawal\")+'</button><button class=\"btn ghost\" data-close>Cancel</button></div>',\nsh=>{\nsh.querySelectorAll(\"[data-chip]\").forEach(b=>b.addEventListener(\"click\",()=>{ $(\"w-amt\").value=b.dataset.chip; check(); }));\nconst check=()=>{ const v=num($(\"w-amt\").value); $(\"w-err\").textContent = v>t.left&&t.left>=0&&!isNaN(v)&&v>0 ? \"That is \"+fmt(v-t.left)+\" \"+CUR+\" more than planned. You can still save it.\" : \"\"; };\n$(\"w-amt\").addEventListener(\"input\",check);\n$(\"w-go\").addEventListener(\"click\",async()=>{\nconst v=num($(\"w-amt\").value); if(!(v>0)){ $(\"w-err\").textContent=\"Enter an amount above 0.\"; return; }\n$(\"w-go\").disabled=true;\nconst at=readDate(\"w-at\"), note=$(\"w-note\").value.trim();\nconst ok = isSave\n? await write(()=>S.db.collection(\"savings\").add({month:k,chargeId:r.id,kind:\"deposit\",amount:v,at,reason:note||(\"Savings from \"+monthLabel(k)+\" salary\"),createdAt:new Date().toISOString()}), fmt(v)+\" \"+CUR+\" moved to savings\")\n: await write(()=>S.db.collection(\"withdrawals\").add(Object.assign({month:k,chargeId:r.id,amount:v,at,note,createdAt:new Date().toISOString()},pt?{partId:pt.id}:{})), fmt(v)+\" \"+CUR+\" withdrawn for \"+(pt?pt.name:r.name));\nif(ok) closeSheet(); else $(\"w-go\").disabled=false;\n});\n});\n}\nfunction sheetUnplanned(k){\nconst cc=calc(k);\nopenSheet('<h2>Unplanned withdrawal</h2><p class=\"hint\">For money taken out that isn\u2019t in your plan. It comes from your spare money: '+money(Math.max(cc.spare,0))+' left.</p>'+\n'<div class=\"field\"><label for=\"u-amt\">Amount ('+CUR+')</label><input class=\"input big-in\" id=\"u-amt\" inputmode=\"decimal\" autocomplete=\"off\"></div>'+\n'<div class=\"field\"><label for=\"u-note\">What was it for?</label><input class=\"input\" id=\"u-note\" autocomplete=\"off\" placeholder=\"e.g. taxi, doctor\"></div>'+dateField(\"u-at\")+\n'<div class=\"err\" id=\"u-err\"></div><div class=\"btn-row\"><button class=\"btn paid\" id=\"u-go\">Record withdrawal</button><button class=\"btn ghost\" data-close>Cancel</button></div>',\n()=>{ $(\"u-amt\").addEventListener(\"input\",()=>{ const v=num($(\"u-amt\").value); $(\"u-err\").textContent = v>0&&v>Math.max(cc.spare,0) ? \"That is \"+fmt(v-Math.max(cc.spare,0))+\" \"+CUR+\" more than your spare money. It will come from your planned charges. You can still save it.\" : \"\"; });\n$(\"u-go\").addEventListener(\"click\",async()=>{\nconst v=num($(\"u-amt\").value), note=$(\"u-note\").value.trim();\nif(!(v>0)){ $(\"u-err\").textContent=\"Enter an amount above 0.\"; return; }\nif(!note){ $(\"u-err\").textContent=\"Write what it was for, so you can recognise it later.\"; return; }\n$(\"u-go\").disabled=true;\nconst ok=await write(()=>S.db.collection(\"withdrawals\").add({month:k,chargeId:null,amount:v,at:readDate(\"u-at\"),note,createdAt:new Date().toISOString()}),\"Unplanned withdrawal saved\");\nif(ok) closeSheet(); else $(\"u-go\").disabled=false;\n}); });\n}\nfunction sheetIncome(k){\nopenSheet('<h2>Extra income</h2><p class=\"hint\">A bonus, a gift, money paid back. It adds to this month\u2019s money in.</p>'+\n'<div class=\"field\"><label for=\"i-name\">From</label><input class=\"input\" id=\"i-name\" autocomplete=\"off\" placeholder=\"e.g. Work bonus\"></div>'+\n'<div class=\"field\"><label for=\"i-amt\">Amount ('+CUR+')</label><input class=\"input big-in\" id=\"i-amt\" inputmode=\"decimal\" autocomplete=\"off\"></div>'+\n'<div class=\"err\" id=\"i-err\"></div><div class=\"btn-row\"><button class=\"btn primary\" id=\"i-go\">Add income</button><button class=\"btn ghost\" data-close>Cancel</button></div>',\n()=>{ $(\"i-go\").addEventListener(\"click\",async()=>{\nconst v=num($(\"i-amt\").value), name=$(\"i-name\").value.trim();\nif(!name){ $(\"i-err\").textContent=\"Write where the money came from.\"; return; }\nif(!(v>0)){ $(\"i-err\").textContent=\"Enter an amount above 0.\"; return; }\n$(\"i-go\").disabled=true;\nconst m=clone(S.months[k]); m.income=[...(m.income||[]),{id:uid(),name,amount:v,at:new Date().toISOString()}];\nconst ok=await write(()=>S.db.doc(\"months/\"+k).set(m),\"Income added\");\nif(ok) closeSheet(); else $(\"i-go\").disabled=false;\n}); });\n}\nfunction sheetSavings(dir){\nconst k=currentKey(); if(!k){ toast(\"Set up a month first.\"); return; }\nconst out=dir===\"out\";\nopenSheet('<h2>'+(out?\"Take out of savings\":\"Add to savings\")+'</h2><p class=\"hint\">Balance now: '+money(savingsBalance())+'.'+(out?\" Money you take out is added to \"+esc(monthLabel(k))+\"\u2019s money in.\":\"\")+'</p>'+\n'<div class=\"field\"><label for=\"s-amt\">Amount ('+CUR+')</label><input class=\"input big-in\" id=\"s-amt\" inputmode=\"decimal\" autocomplete=\"off\"></div>'+\n'<div class=\"field\"><label for=\"s-why\">Reason</label><input class=\"input\" id=\"s-why\" autocomplete=\"off\" placeholder=\"'+(out?\"e.g. a big purchase\":\"e.g. leftover from last month\")+'\"></div>'+dateField(\"s-at\")+\n'<div class=\"err\" id=\"s-err\"></div><div class=\"btn-row\"><button class=\"btn '+(out?\"paid\":\"save\")+'\" id=\"s-go\">'+(out?\"Take out\":\"Add to savings\")+'</button><button class=\"btn ghost\" data-close>Cancel</button></div>',\n()=>{ $(\"s-go\").addEventListener(\"click\",async()=>{\nconst v=num($(\"s-amt\").value), why=$(\"s-why\").value.trim();\nif(!(v>0)){ $(\"s-err\").textContent=\"Enter an amount above 0.\"; return; }\nif(!why){ $(\"s-err\").textContent=\"Write a reason. It keeps your savings history clear.\"; return; }\n$(\"s-go\").disabled=true;\nconst ok=await write(()=>S.db.collection(\"savings\").add({month:k,chargeId:null,kind:out?\"withdraw\":\"deposit\",amount:out?-v:v,at:readDate(\"s-at\"),reason:why,createdAt:new Date().toISOString()}), out?\"Taken out of savings\":\"Added to savings\");\nif(ok) closeSheet(); else $(\"s-go\").disabled=false;\n}); });\n}\n/* plan editor (used by Edit plan and New month) */\nfunction planEditorHtml(rows){\nreturn '<div id=\"pl-rows\">'+rows.map(planRowHtml).join(\"\")+'</div><button class=\"btn small\" id=\"pl-add\">+ Add a charge</button>';\n}\nfunction partRowHtml(pt){\nreturn '<div class=\"part-row\" data-part=\"'+esc(pt.id)+'\">'+\n'<input class=\"input\" data-pf=\"name\" aria-label=\"Part name\" value=\"'+esc(pt.name)+'\" placeholder=\"Part name\">'+\n'<input class=\"input\" data-pf=\"planned\" aria-label=\"Part amount\" inputmode=\"decimal\" value=\"'+esc(pt.planned)+'\" placeholder=\"0\">'+\n'<button class=\"x\" data-del-part>Remove</button></div>';\n}\nfunction planRowHtml(r){\nconst split=!!(r.parts&&r.parts.length);\nconst total=split?sum(r.parts,x=>Number(x.planned)||0):r.planned;\nreturn '<div class=\"plan-row'+(split?' is-split':'')+'\" data-row=\"'+esc(r.id)+'\">'+\n'<input class=\"input\" data-f=\"name\" aria-label=\"Charge name\" value=\"'+esc(r.name)+'\" placeholder=\"Charge name\">'+\n'<input class=\"input\" data-f=\"planned\" aria-label=\"Amount\" inputmode=\"decimal\" value=\"'+esc(total)+'\" placeholder=\"0\"'+(split?' readonly':'')+'>'+\n'<div class=\"wide\"><select class=\"input\" data-f=\"type\" aria-label=\"Type\">'+\n'<option value=\"fixed\"'+(r.type!==\"envelope\"&&r.type!==\"savings\"?\" selected\":\"\")+'>Withdraw at once</option>'+\n'<option value=\"envelope\"'+(r.type===\"envelope\"?\" selected\":\"\")+'>Envelope (withdraw in parts)</option>'+\n'<option value=\"savings\"'+(r.type===\"savings\"?\" selected\":\"\")+'>Goes to savings</option></select>'+\n'<button class=\"x\" data-split>'+(split?'+ Add part':'Split')+'</button><button class=\"x\" data-del-row>Remove</button></div>'+\n'<div class=\"parts-edit\">'+(split?r.parts.map(partRowHtml).join(\"\"):\"\")+'</div></div>';\n}\nfunction splitRow(row){\nconst amt=row.querySelector('[data-f=\"planned\"]'), box=row.querySelector(\".parts-edit\"), d=document.createElement(\"div\");\nif(!row.classList.contains(\"is-split\")){\nd.innerHTML=partRowHtml({id:uid(),name:row.querySelector('[data-f=\"name\"]').value.trim(),planned:amt.value})+partRowHtml({id:uid(),name:\"\",planned:\"\"});\nrow.classList.add(\"is-split\"); amt.readOnly=true; row.querySelector(\"[data-split]\").textContent=\"+ Add part\";\n} else d.innerHTML=partRowHtml({id:uid(),name:\"\",planned:\"\"});\nconst added=[...d.children]; added.forEach(x=>box.appendChild(x)); added[added.length-1].querySelector(\"input\").focus();\n}\nfunction syncSplit(row){\nconst t=sum([...row.querySelectorAll('.part-row [data-pf=\"planned\"]')],i=>num(i.value)||0);\nrow.querySelector('[data-f=\"planned\"]').value=t?String(t):\"\";\n}\nfunction bindPlanEditor(sh, onChange){\nconst box=$(\"pl-rows\");\nconst changed=()=>{ box.querySelectorAll(\".plan-row.is-split\").forEach(syncSplit); onChange&&onChange(); };\nbox.addEventListener(\"input\",changed);\nbox.addEventListener(\"click\",e=>{\nconst b=e.target.closest(\"button\"); if(!b) return;\nconst row=b.closest(\".plan-row\"); if(!row) return;\nif(b.hasAttribute(\"data-del-row\")) row.remove();\nelse if(b.hasAttribute(\"data-split\")) splitRow(row);\nelse if(b.hasAttribute(\"data-del-part\")){\nb.closest(\".part-row\").remove();\nif(!row.querySelector(\".part-row\")){ row.classList.remove(\"is-split\"); row.querySelector('[data-f=\"planned\"]').readOnly=false; row.querySelector(\"[data-split]\").textContent=\"Split\"; }\n}\nchanged();\n});\n$(\"pl-add\").addEventListener(\"click\",()=>{\nconst d=document.createElement(\"div\"); d.innerHTML=planRowHtml({id:uid(),name:\"\",planned:\"\",type:\"fixed\"});\nconst row=d.firstChild; box.appendChild(row); row.querySelector(\"input\").focus(); changed();\n});\n}\nfunction readPlan(){\nconst out=[]; let err=\"\";\ndocument.querySelectorAll(\"#pl-rows .plan-row\").forEach(row=>{\nconst name=row.querySelector('[data-f=\"name\"]').value.trim();\nconst type=row.querySelector('[data-f=\"type\"]').value;\nlet parts=null;\nif(row.classList.contains(\"is-split\")){\nparts=[];\nrow.querySelectorAll(\".part-row\").forEach(pr=>{\nconst pn=pr.querySelector('[data-pf=\"name\"]').value.trim(), pp=num(pr.querySelector('[data-pf=\"planned\"]').value||\"0\");\nif(!pn&&!(pp>0)) return;\nif(!pn) err=err||\"Every part needs a name.\";\nelse if(isNaN(pp)||pp<0) err=err||\"Check the amount for \"+pn+\".\";\nparts.push({id:pr.dataset.part,name:pn,planned:isNaN(pp)?0:pp});\n});\nif(!parts.length) parts=null;\n}\nconst p=parts?sum(parts,x=>x.planned):num(row.querySelector('[data-f=\"planned\"]').value||\"0\");\nif(!name&&!(p>0)) return;\nif(!name) err=err||\"Every charge needs a name.\";\nelse if(isNaN(p)||p<0) err=err||\"Check the amount for \"+name+\".\";\nelse if(parts&&type===\"savings\") err=err||\"Savings can\\u2019t be split. Remove the parts from \"+name+\".\";\nconst o={id:row.dataset.row,name,planned:isNaN(p)?0:p,type}; if(parts) o.parts=parts;\nout.push(o);\n});\nreturn {rows:out,err};\n}\nfunction sheetPlan(k){\nconst m=S.months[k];\nopenSheet('<h2>Edit plan \u00b7 '+esc(monthLabel(k))+'</h2>'+\n'<div class=\"field\"><label for=\"p-sal\">Salary ('+CUR+')</label><input class=\"input big-in\" id=\"p-sal\" inputmode=\"decimal\" value=\"'+esc(m.salary)+'\"></div>'+\nplanEditorHtml(m.charges||[])+'<p class=\"hint\" id=\"p-tot\"></p><div class=\"err\" id=\"p-err\"></div>'+\n'<div class=\"btn-row\"><button class=\"btn primary\" id=\"p-go\">Save plan</button><button class=\"btn ghost\" data-close>Cancel</button></div>',\nsh=>{\nconst tot=()=>{ const {rows}=readPlan(); const s=num($(\"p-sal\").value)||0; const t=sum(rows,r=>r.planned); const inc=sum(m.income||[],i=>Number(i.amount)||0);\n$(\"p-tot\").textContent=\"Planned \"+money(t)+\" of \"+money(s+inc)+\" \u00b7 \"+(s+inc-t>=0?money(s+inc-t)+\" not planned\":money(t-s-inc)+\" over\"); };\nbindPlanEditor(sh,tot); $(\"p-sal\").addEventListener(\"input\",tot); tot();\n$(\"p-go\").addEventListener(\"click\",async()=>{\nconst {rows,err}=readPlan(); const s=num($(\"p-sal\").value);\nif(!(s>=0)){ $(\"p-err\").textContent=\"Enter your salary.\"; return; }\nif(err){ $(\"p-err\").textContent=err; return; }\nconst removed=(m.charges||[]).filter(c=>!rows.some(r=>r.id===c.id));\nconst blocked=removed.find(c=>S.withdrawals.some(w=>w.month===k&&w.chargeId===c.id)||S.savings.some(e=>e.month===k&&e.chargeId===c.id));\nif(blocked){ $(\"p-err\").textContent=blocked.name+\" has withdrawals this month. Delete them from the log first, or keep the charge.\"; return; }\nfor(const r of rows){\nconst old=(m.charges||[]).find(c=>c.id===r.id); if(!old) continue;\nconst W=S.withdrawals.filter(w=>w.month===k&&w.chargeId===r.id);\nif(r.parts&&!(old.parts&&old.parts.length)&&W.length){ $(\"p-err\").textContent=r.name+\" already has withdrawals this month. Split it next month, or delete them from the log first.\"; return; }\nconst gone=(old.parts||[]).find(pt=>!(r.parts||[]).some(x=>x.id===pt.id)&&W.some(w=>w.partId===pt.id));\nif(gone){ $(\"p-err\").textContent=r.name+\" \\u00b7 \"+gone.name+\" has withdrawals this month. Delete them from the log first, or keep it.\"; return; }\n}\n$(\"p-go\").disabled=true;\nconst nm=clone(m); nm.salary=s; nm.charges=rows;\nconst ok=await write(()=>S.db.doc(\"months/\"+k).set(nm),\"Plan saved\");\nif(ok) closeSheet(); else $(\"p-go\").disabled=false;\n});\n});\n}\nfunction sheetNewMonth(){\nconst prevKey=currentKey();\nconst newKey=prevKey?addMonths(prevKey,1):(()=>{const d=new Date();return d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\");})();\nif(S.months[newKey]){ toast(monthLabel(newKey)+\" already exists.\"); return; }\nconst prev=prevKey?calc(prevKey):null;\nconst leftover=prev&&!prev.m.imported?Math.max(Math.round(prev.inBank*100)/100,0):0;\nconst rows=prev?clone(prev.m.charges||[]):[{id:\"rent\",name:\"Rent & bills\",planned:\"\",type:\"fixed\"},{id:\"food\",name:\"Food\",planned:\"\",type:\"fixed\"},{id:\"savings\",name:\"Savings\",planned:\"\",type:\"savings\"}];\nconst salaryOf=monthLabel(addMonths(newKey,-1));\nopenSheet('<h2>Start '+esc(monthLabel(newKey))+'</h2><p class=\"hint\">Salary of '+esc(salaryOf)+'. Charges are copied from '+(prev?esc(monthLabel(prevKey)):\"a starter list\")+'. Change any amount.</p>'+\n'<div class=\"field\"><label for=\"n-sal\">Salary received ('+CUR+')</label><input class=\"input big-in\" id=\"n-sal\" inputmode=\"decimal\" autocomplete=\"off\" value=\"'+(prev?esc(prev.m.salary):\"\")+'\"></div>'+\n(leftover>0?'<div class=\"field\"><label>'+esc(monthLabel(prevKey))+' left '+money(leftover)+' in the bank</label>'+\n'<label class=\"radio\"><input type=\"radio\" name=\"n-left\" value=\"income\" checked><span>Add it to '+esc(monthLabel(newKey))+'\u2019s money</span></label>'+\n'<label class=\"radio\"><input type=\"radio\" name=\"n-left\" value=\"savings\"><span>Move it to savings</span></label>'+\n'<label class=\"radio\"><input type=\"radio\" name=\"n-left\" value=\"none\"><span>Leave it out</span></label></div>':'')+\n'<h3 style=\"font-size:16px\">Charges</h3>'+planEditorHtml(rows)+'<p class=\"hint\" id=\"n-tot\"></p><div class=\"err\" id=\"n-err\"></div>'+\n'<div class=\"btn-row\"><button class=\"btn primary\" id=\"n-go\">Start '+esc(monthLabel(newKey))+'</button><button class=\"btn ghost\" data-close>Cancel</button></div>',\nsh=>{\nconst tot=()=>{ const {rows}=readPlan(); const s=num($(\"n-sal\").value)||0; const lo=(document.querySelector('input[name=\"n-left\"]:checked')||{}).value===\"income\"?leftover:0; const t=sum(rows,r=>r.planned);\n$(\"n-tot\").textContent=\"Planned \"+money(t)+\" of \"+money(s+lo)+\" \u00b7 \"+(s+lo-t>=0?money(s+lo-t)+\" not planned\":money(t-s-lo)+\" over\"); };\nbindPlanEditor(sh,tot); $(\"n-sal\").addEventListener(\"input\",tot); sh.querySelectorAll('input[name=\"n-left\"]').forEach(r=>r.addEventListener(\"change\",tot)); tot();\n$(\"n-go\").addEventListener(\"click\",async()=>{\nconst {rows,err}=readPlan(); const s=num($(\"n-sal\").value);\nif(!(s>0)){ $(\"n-err\").textContent=\"Enter the salary you received.\"; return; }\nif(err){ $(\"n-err\").textContent=err; return; }\nif(!rows.length){ $(\"n-err\").textContent=\"Add at least one charge.\"; return; }\n$(\"n-go\").disabled=true;\nconst choice=(document.querySelector('input[name=\"n-left\"]:checked')||{}).value||\"none\";\nconst nm={key:newKey,salaryOf,salary:s,charges:rows,income:[],closed:false,createdAt:new Date().toISOString()};\nif(leftover>0&&choice===\"income\") nm.income.push({id:uid(),name:\"Leftover from \"+monthLabel(prevKey),amount:leftover,at:new Date().toISOString()});\nconst ok=await write(async()=>{\nawait S.db.doc(\"months/\"+newKey).set(nm);\nif(leftover>0&&choice===\"savings\") await S.db.collection(\"savings\").add({month:newKey,chargeId:null,kind:\"deposit\",fromLeftover:true,amount:leftover,at:new Date().toISOString(),reason:\"Leftover from \"+monthLabel(prevKey),createdAt:new Date().toISOString()});\nif(prevKey){ const pm=clone(S.months[prevKey]); pm.closed=true; await S.db.doc(\"months/\"+prevKey).set(pm); }\nawait S.db.doc(\"settings/app\").set({...(S.settings||{}),currentMonth:newKey});\n}, monthLabel(newKey)+\" started\");\nif(ok){ S.viewKey=newKey; S.pendingKey=newKey; closeSheet(); location.hash=\"#month\"; route(); window.scrollTo(0,0); } else $(\"n-go\").disabled=false;\n});\n});\n}\n/* ---------- export ---------- */\nfunction csvCell(v){ const s=String(v==null?\"\":v); return /[\",\\n]/.test(s)?'\"'+s.replace(/\"/g,'\"\"')+'\"':s; }\nasync function exportCsv(){\nif(!S.dl) return;\nconst lines=[[\"type\",\"month\",\"date\",\"category\",\"amount_dh\",\"planned_dh\",\"note\"].join(\",\")];\nsortedKeys().forEach(k=>{ const m=S.months[k];\nlines.push([\"salary\",k,\"\",\"Salary\",m.salary,\"\",m.salaryOf?(\"Salary of \"+m.salaryOf):\"\"].map(csvCell).join(\",\"));\n(m.income||[]).forEach(i=>lines.push([\"income\",k,i.at||\"\",i.name,i.amount,\"\",\"\"].map(csvCell).join(\",\")));\n(m.charges||[]).forEach(c=>lines.push([\"plan\",k,\"\",c.name,\"\",c.planned,c.type].map(csvCell).join(\",\")));\n});\n[...S.withdrawals].sort((a,b)=>(a.month+(a.at||\"\")).localeCompare(b.month+(b.at||\"\"))).forEach(w=>{\nlines.push([\"withdrawal\",w.month,w.at||\"\",labelFor(S.months[w.month]||{},w.chargeId,w.note,w.partId),w.amount,\"\",w.note||\"\"].map(csvCell).join(\",\"));\n});\n[...S.savings].sort((a,b)=>(a.month+(a.at||\"\")).localeCompare(b.month+(b.at||\"\"))).forEach(e=>{\nlines.push([\"savings_\"+e.kind,e.month,e.at||\"\",\"Savings\",e.amount,\"\",e.reason||\"\"].map(csvCell).join(\",\"));\n});\nconst r=await saveFile(\"salary-manager-\"+new Date().toISOString().slice(0,10)+\".csv\",lines.join(\"\\n\"),\"text/csv\");\nif(r!==\"cancelled\") toast(\"CSV ready\");\n}\n/* ---------- backup / restore ---------- */\nasync function exportBackup(){\nconst now=new Date().toISOString();\nconst body=JSON.stringify({app:\"salary-manager\",version:1,exportedAt:now,data:LocalDB.dump()});\nconst r=await saveFile(\"salary-manager-backup-\"+now.slice(0,10)+\".json\",body,\"application/json\");\nif(r===\"cancelled\") return;\nawait write(()=>S.db.doc(\"settings/app\").set({...(S.settings||{}),lastBackupAt:now}),\"Backup saved\");\n}\nfunction normalizeBackup(obj){\nlet data=null;\nif(obj&&obj.app===\"salary-manager\"&&obj.data&&typeof obj.data===\"object\") data=obj.data;\nelse if(obj&&obj.months&&typeof obj.months===\"object\"){ data={}; for(const [c,docs] of Object.entries(obj)) if(docs&&typeof docs===\"object\") for(const [id,d] of Object.entries(docs)) data[c+\"/\"+id]=d; }\nif(!data) return null;\nconst ok={}; let months=0, bal=0;\nfor(const [p,d] of Object.entries(data)){\nconst parts=p.split(\"/\");\nif(parts.length!==2||![\"months\",\"withdrawals\",\"savings\",\"settings\"].includes(parts[0])||!d||typeof d!==\"object\"||Array.isArray(d)) continue;\nok[p]=d; if(parts[0]===\"months\") months++; if(parts[0]===\"savings\") bal+=Number(d.amount)||0;\n}\nreturn months?{data:ok,months,bal,exportedAt:obj.exportedAt||null}:null;\n}\nfunction sheetImport(){\nopenSheet('<h2>Restore a backup</h2><p class=\"hint\">Choose a Salary Manager backup file (.json). It replaces the data on this phone.</p>'+\n'<div class=\"field\"><label for=\"imp-file\">Backup file</label><input class=\"input\" type=\"file\" id=\"imp-file\" accept=\".json,application/json\"></div>'+\n'<div class=\"hint\" id=\"imp-info\"></div><div class=\"err\" id=\"imp-err\"></div>'+\n'<div class=\"btn-row\"><button class=\"btn primary\" id=\"imp-go\" disabled>Restore this backup</button><button class=\"btn ghost\" data-close>Cancel</button></div>',\n()=>{\nlet parsed=null;\n$(\"imp-file\").addEventListener(\"change\",async()=>{\nparsed=null; $(\"imp-go\").disabled=true; $(\"imp-info\").textContent=\"\"; $(\"imp-err\").textContent=\"\";\nconst f=$(\"imp-file\").files[0]; if(!f) return;\ntry{ parsed=normalizeBackup(JSON.parse(await f.text())); }catch(e){ parsed=null; }\nif(!parsed){ $(\"imp-err\").textContent=\"This file isn\\u2019t a Salary Manager backup. Choose the .json file you saved from the app.\"; return; }\n$(\"imp-info\").textContent=\"Found \"+parsed.months+\" months, savings balance \"+money(parsed.bal)+(parsed.exportedAt?\", saved \"+new Date(parsed.exportedAt).toLocaleDateString(\"en-GB\",{day:\"numeric\",month:\"short\",year:\"numeric\"}):\"\")+\".\"+(LocalDB.isEmpty()?\"\":\" The data now on this phone will be replaced.\");\n$(\"imp-go\").disabled=false;\n});\n$(\"imp-go\").addEventListener(\"click\",()=>{\nif(!parsed) return;\ntry{ LocalDB.replaceAll(parsed.data); S.viewKey=null; closeSheet(); toast(\"Backup restored\"); location.hash=\"#month\"; route(); }\ncatch(e){ $(\"imp-err\").textContent=\"Phone storage is full. Free some space and try again.\"; }\n});\n});\n}\nboot();\n})();\n</script>\n</body>\n</html>";
const builtIn = () => new Response(APP_HTML, {headers: {"Content-Type": "text/html; charset=utf-8"}});
const isHtml = u => u === "./" || u === "./index.html";
// put back any saved file that is missing (the page from the built-in copy, the rest from the internet)
const heal = () => caches.open(CACHE).then(c => Promise.all(ASSETS.map(u => c.match(u).then(hit => {
  if (hit) return;
  if (isHtml(u)) return c.put(u, builtIn());
  return fetch(u, {cache: "no-cache"}).then(r => { if (r.ok) return c.put(u, r); });
}).catch(() => {})))).catch(() => {});
self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => Promise.all([c.put("./", builtIn()), c.put("./index.html", builtIn())]))
    .then(heal).then(() => self.skipWaiting()));
});
self.addEventListener("activate", e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith("salary-manager-") && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()).then(heal));
});
// offline: the last page seen online, or the built-in copy if the saved one is gone
const fromCache = () => caches.match("./index.html").then(hit => hit || builtIn()).catch(() => builtIn());
self.addEventListener("fetch", e => {
  const req = e.request, url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return;
  const isPage = req.mode === "navigate" || url.pathname.endsWith("/") || url.pathname.endsWith("/index.html");
  if (isPage) {
    e.waitUntil(heal());
    if (self.navigator && self.navigator.onLine === false) { e.respondWith(fromCache()); return; }
    // with signal: newest page (2.5 s limit), otherwise the saved one
    e.respondWith(new Promise(resolve => {
      let done = false;
      const timer = setTimeout(() => { if (!done) { done = true; resolve(fromCache()); } }, 2500);
      fetch(req.url, {cache: "no-cache", credentials: "same-origin"}).then(res => {
        if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put("./index.html", copy)); }
        if (!done) { done = true; clearTimeout(timer); resolve(res.ok ? res : fromCache()); }
      }).catch(() => { if (!done) { done = true; clearTimeout(timer); resolve(fromCache()); } });
    }));
    return;
  }
  // fonts, icons, manifest: saved copy first
  e.respondWith(caches.match(req, {ignoreSearch: true}).then(hit => hit || fetch(req).then(res => {
    if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
    return res;
  })).catch(() => Response.error()));
});
